mapper.select:
SELECT l.ai_log_id, l.user_id, u.name AS user_name, l.feature_code, l.request_prompt, l.response_text, l.model_name, l.success_yn, l.error_message, l.created_at FROM ai_usage_logs l JOIN users u ON u.user_id = l.user_id
l.feature_code = #{featureCode}
AND l.created_at >= CAST(#{fromDate} AS DATE)
AND l.created_at < CAST(#{toDate} AS DATE) + INTERVAL '1 day'
ORDER BY l.created_at DESC, l.ai_log_id DESC LIMIT #{limit}
